typedef void (*callback_t)(int, const char *);
void register_callback(callback_t cb);
void invoke_callback(callback_t cb, int code, const char *message) {
    if (cb) {
        cb(code, message);
    }
}
void my_callback(int code, const char *msg) {
    printf("Callback invoked with code %d and message: %s\n", code, msg);
}
int main() {
    callback_t cb = &my_callback; // Assign function pointer
    register_callback(cb);
    invoke_callback(cb, 42, "Deep C Secrets");
    return 0;
}
